// src/app/core/interceptors/api-error.interceptor.ts
var apiErrorInterceptor = (request, next) => {
  const notifications = inject(NotificationService);
  return next(request).pipe(catchError((error) => {
    notifications.error(toMessage(error));
    return throwError(() => error);
  }));
};
function toMessage(error) {
  if (!(error instanceof HttpErrorResponse)) {
    return "Une erreur inattendue est survenue.";
  }
  if (error.status === 0) {
    return "Serveur injoignable. V\xE9rifiez que radiology-api est d\xE9marr\xE9.";
  }
  const body = error.error;
  const violations = body?.violations ?? [];
  if (violations.length > 0) {
    return violations.map((violation) => `${violation.field} : ${violation.message}`).join(" \u2014 ");
  }
  return body?.message ?? `Erreur ${error.status}.`;
}

// src/app/app.config.ts
var appConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideZoneChangeDetection({ eventCoalescing: true }),
    provideRouter(routes, withComponentInputBinding()),
    provideHttpClient(withInterceptors([apiErrorInterceptor])),
    provideAnimationsAsync()
  ]
};

